FROM jsonb_populate_recordset(NULL::page_recipe_overrides, $backup$[{"recipe_path": "dso", "recipe_id": "dso-data-room", "label": "Data room", "description": "a metrics-first page for a numbers-driven executive audience", "style_notes": "Boardroom tone: every section anchored by a real network-level metric. The comparison is the centerpiece — make its rows substantive. Dark, confident backgrounds.", "enabled": true, "updated_by": 36476, "created_at": "2026-06-27T21:20:46.64404+00:00", "updated_at": "2026-07-05T21:34:24.976953+00:00", "skeleton": ["dso-heartland-hero", "dso-stat-showcase", "dso-comparison", "dso-ai-feature", "dso-success-stories", "dso-pilot-steps", "dso-final-cta OR dso-cta-capture"], "is_custom": false, "sort_order": 0}, {"recipe_path": "dso", "recipe_id": "dso-narrative", "label": "Customer narrative", "description": "a structured growth page modeled on a flagship DSO partner growth page: a stat-backed hero, an ROI proof grid, the core challenges, an old-way vs new-way contrast, one capability spotlight, then stacked customer proof", "style_notes": "A confident, executive growth story told through outcomes, not a feature list. Open on a dark, full-bleed hero whose headline names the growth outcome, with a 3–4 metric stat bar underneath. Follow with an ROI stat grid that quantifies the result, then 3–4 sharply-named operational challenges. The old-way vs new-way comparison is the centerpiece — make both columns substantive and specific. Spotlight ONE capability with its own supporting metrics and an image, then stack 3 customer success stories using approved case studies only (each with a real logo, stat, and quote). Close on a single, unmissable CTA. Dark, premium backgrounds; every section earns its scroll.", "enabled": true, "updated_by": 1, "created_at": "2026-06-29T23:06:21.975298+00:00", "updated_at": "2026-06-29T23:06:21.975298+00:00", "skeleton": ["dso-heartland-hero", "dso-problem", "dso-stat-showcase", "dso-ai-feature", "dso-bento-outcomes", "dso-success-stories", "dso-final-cta OR dso-cta-capture"], "is_custom": false, "sort_order": 0}, {"recipe_path": "dso", "recipe_id": "dso-pilot-push", "label": "Pilot push", "description": "an action-oriented page that drives a pilot-program commitment", "style_notes": "Momentum toward one ask: name the challenges fast, show the capability that removes them, then make the pilot timeline feel concrete and low-risk. CTAs all point at booking the pilot.", "enabled": true, "updated_by": 1, "created_at": "2026-06-27T18:25:35.8476+00:00", "updated_at": "2026-06-29T23:05:39.772091+00:00", "skeleton": ["dso-heartland-hero", "dso-problem", "dso-stat-showcase", "dso-comparison", "dso-ai-feature", "dso-success-stories", "dso-pilot-steps", "dso-final-cta"], "is_custom": false, "sort_order": 0}, {"recipe_path": "dso-practices", "recipe_id": "dso-practices-objections", "label": "Objection handling", "description": "a trust-building page that converts skeptical practices by answering doubts head-on", "style_notes": "Meet skepticism directly: contrast the old way vs the new way with paired, specific bullets, answer the real objections in the FAQ.", "enabled": true, "updated_by": 1, "created_at": "2026-06-29T23:03:11.881938+00:00", "updated_at": "2026-06-29T23:03:50.134624+00:00", "skeleton": ["dso-practice-hero", "dso-paradigm-shift", "dso-partnership-perks", "dso-testimonials", "dso-activation-steps", "dso-faq", "dso-promises"], "is_custom": false, "sort_order": 0}, {"recipe_path": "dso-practices", "recipe_id": "dso-practices-onboarding", "label": "Onboarding story", "description": "a warm page that makes getting started feel effortless for a practice", "style_notes": "Reassuring and concrete: lead with how fast onboarding is, show the dedicated support behind it, and put real people (the team) at the close. Practice-level numbers (chair time, fit rate), not network KPIs.", "enabled": true, "updated_by": 1, "created_at": "2026-06-29T23:04:08.308572+00:00", "updated_at": "2026-06-29T23:04:08.308572+00:00", "skeleton": ["dso-practice-hero", "dso-activation-steps", "dso-split-feature", "dso-stat-row", "dso-promises", "dso-meet-team", "dso-faq"], "is_custom": false, "sort_order": 0}, {"recipe_path": "dso-practices", "recipe_id": "dso-practices-product-push", "label": "Product push", "description": "a catalog-forward page that showcases products and exclusive offers", "style_notes": "Merchandised and specific: real product names with turnaround/pricing detail, offers framed as network-exclusive perks, peer testimonials for credibility. Keep copy warm, not enterprise.", "enabled": true, "updated_by": 1, "created_at": "2026-06-29T23:03:47.132958+00:00", "updated_at": "2026-06-29T23:06:47.92096+00:00", "skeleton": ["dso-practice-hero", "dso-products-grid", "dso-promo-cards", "dso-testimonials OR dso-stat-row", "dso-partnership-perks", "dso-meet-team", "dso-activation-steps"], "is_custom": false, "sort_order": 0}, {"recipe_path": "freeform", "recipe_id": "freeform-conversion-tight", "label": "Conversion-tight", "description": "a focused direct-response page built to convert in one scroll", "style_notes": "Every section earns its scroll: benefit-dense copy, social proof early, a clear 3-step path, then the pricing/objection answer (use glass-pricing-tiers ONLY when the brief provides real prices — otherwise the comparison) and one unmissable closing CTA. No decorative detours; CTAs repeat the same single action.", "enabled": true, "updated_by": 36476, "created_at": "2026-06-27T04:43:17.792956+00:00", "updated_at": "2026-07-05T21:29:26.199236+00:00", "skeleton": ["dandy-hero-v7-s3 OR dandy-product-hero", "trust-bar", "pas-section OR value-pillars-divided-columns", "dandy-vertical-tabs", "zigzag-features OR feature-big-features", "dandy-side-image-v6", "quote-with-image", "aurora-cta-finale OR split-form-final-cta"], "is_custom": false, "sort_order": 0}, {"recipe_path": "freeform", "recipe_id": "freeform-custom-5271f3f794", "label": "Big Block Page", "description": "Home-page quality page with many big, image heavy blocks", "style_notes": "Use this when you need a homepage quality page or pillar piece of content with many diverse sections and formats.", "enabled": true, "updated_by": 27, "created_at": "2026-07-02T03:23:40.372892+00:00", "updated_at": "2026-07-02T03:46:11.577102+00:00", "skeleton": ["mega-menu-nav", "ai-scan-hero", "dso-split-feature", "feature-photo-cards", "features-spotlight-cards", "editorial-carousel", "value-pillars-outlined-cards", "feature-card-grid", "dso-faq", "cta-split-image"], "is_custom": true, "sort_order": 4}, {"recipe_path": "freeform", "recipe_id": "freeform-custom-53543a95fe", "label": "Full bleed square statement", "description": "Use this with an image heavy brand with many large, full bleed images to choose from like construction or Procore.", "style_notes": "Use all square or 0px border radiuses on images and sections when its an option make sure all cards have images please", "enabled": true, "updated_by": 36476, "created_at": "2026-06-29T02:49:46.931841+00:00", "updated_at": "2026-07-05T21:32:41.648232+00:00", "skeleton": ["full-bleed-hero OR ai-scan-hero", "stat-row", "value-pillars-color-block-cards", "feature-big-features", "feature-photo-cards", "quote-with-image", "aurora-cta-finale"], "is_custom": true, "sort_order": 3}, {"recipe_path": "freeform", "recipe_id": "freeform-custom-7c02f1d07e", "label": "Copy-heavy Credible", "description": "Use this when there is a lot of copy and the site looks more premium.", "style_notes": "Use when you need room for copy and a premium look. always do the full bleed heartland hero layout with full bleed background image because it looks the best. use centered headline with dandy vertical tabs and make sure you use a similar character count as the default blocks.", "enabled": true, "updated_by": 36476, "created_at": "2026-06-27T22:20:30.482387+00:00", "updated_at": "2026-07-05T21:31:20.925143+00:00", "skeleton": ["dso-heartland-he