rt_order": 0}, {"recipe_path": "freeform", "recipe_id": "freeform-editorial", "label": "Editorial", "description": "a premium magazine-style page that persuades with story and typography", "style_notes": "Premium, unhurried pacing: generous whitespace, long-form copy moments, one strong image per section. Let the typographic hero / bold-statement carry a single load-bearing claim. Avoid dense grids.", "enabled": true, "updated_by": 1, "created_at": "2026-06-27T18:31:54.704671+00:00", "updated_at": "2026-07-06T21:45:20.004589+00:00", "skeleton": ["ai-scan-hero OR full-bleed-hero", "dandy-columns-v2 OR dandy-columns-v3", "value-pillars-color-block-cards", "benefits-alternating-rows OR zigzag-features", "gallery-split-feature", "case-studies OR case-study-spotlight-feature", "aurora-cta-finale"], "is_custom": false, "sort_order": 0}, {"recipe_path": "freeform", "recipe_id": "freeform-showcase-heavy", "label": "Showcase-heavy", "description": "a visual-first page where imagery and motion do the persuading", "style_notes": "Image-led and kinetic: big full-bleed visuals, short punchy copy, minimal bullet lists. Every section should have a strong visual anchor; keep text blocks tight.", "enabled": true, "updated_by": 36476, "created_at": "2026-06-27T19:07:32.064227+00:00", "updated_at": "2026-07-05T21:27:22.149649+00:00", "skeleton": ["launch-spotlight-hero OR cinematic-video-hero", "pas-split-image OR pas-section OR value-pillars-outlined-cards", "how-it-works-horizontal-stepper OR how-it-works-alternating", "features-spotlight-cards OR glass-bento-features", "quote-carousel OR case-studies", "gallery-split-feature", "aurora-cta-finale"], "is_custom": false, "sort_order": 0}, {"recipe_path": "freeform", "recipe_id": "freeform-story-led", "label": "Story-led", "description": "a cinematic narrative page that walks the visitor through a transformation", "style_notes": "Cinematic arc: open atmospheric, build the problem→transformation narrative section by section, land on one human proof moment (the testimonial wall reads as many voices) before the close. Favor depth over breadth — fewer, richer sections.", "enabled": true, "updated_by": 36476, "created_at": "2026-06-27T19:08:35.550807+00:00", "updated_at": "2026-07-05T21:28:50.418948+00:00", "skeleton": ["cinematic-video-hero OR ai-scan-hero", "trust-bar OR stat-row", "pas-section OR value-pillars-color-block-cards", "benefits-alternating-rows", "dandy-columns-v2 OR value-pillars-outlined-cards OR feature-card-grid", "single-quote OR case-studies", "cta-split-image"], "is_custom": false, "sort_order": 0}, {"recipe_path": "microsite", "recipe_id": "microsite-benefits-led", "label": "Benefits-led", "description": "a value-forward page that leads with what the account gains and how it works", "style_notes": "Lead with the payoff: benefit/value cards up top, a simple how-it-works path, then credibility (a metrics bar or a stats row) and a peer quote. Keep copy benefit-dense and concrete; every section answers \"what's in it for them\".", "enabled": true, "updated_by": 36476, "created_at": "2026-06-28T01:42:11.962552+00:00", "updated_at": "2026-07-05T21:37:09.778658+00:00", "skeleton": ["bento-mosaic-hero OR ai-scan-hero", "value-pillars-outlined-cards", "benefits-alternating-rows OR zigzag-features", "dandy-side-image-v6", "feature-card-grid", "single-quote", "bottom-cta"], "is_custom": false, "sort_order": 0}, {"recipe_path": "microsite", "recipe_id": "microsite-comparison-led", "label": "Premium microsite", "description": "Premium page with the most premium blocks", "style_notes": "Built to dislodge an incumbent: frame the cost of the status quo, then make the old-way vs new-way comparison the centerpiece — both columns specific and substantive. Reinforce with the core benefits and one strong real number, then a peer quote and a clear switch CTA.", "enabled": true, "updated_by": 1, "created_at": "2026-06-28T01:42:04.786808+00:00", "updated_at": "2026-07-07T01:05:06.085382+00:00", "skelet